#define MAX_LEN 1024

int main(int argc, char **argv)
{
	char buf[MAX_LEN];
	int fd;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	ret = read(fd, buf, MAX_LEN);
	if (ret < 0) {
		perror("read");
		exit(1);
	}

	if (strstr(buf, "1"))
		printf("1\n");
	else if (strstr(buf, "0"))
		printf("0\n");
	else
		printf("not sure\n");

	close(fd);

	return 0;
}
