#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>

#define MAX_SIZE 1024

int main(int argc, char *argv[]) {
	int fd;
	char *buf;
	int i;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, MAX_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	for (i = 0; i < MAX_SIZE; i++) {
		if (buf[i] == '\n') {
			buf[i] = '\0';
			break;
		}
	}

	printf("%s\n", buf);

	munmap(buf, MAX_SIZE);
	close(fd);

	return 0;
}
