#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_LEN 1024

int main(int argc, char *argv[])
{
	char buf[MAX_LEN];
	int fd;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		printf("open %s failed: %s\n", argv[1], strerror(errno));
		return -1;
	}

	ret = read(fd, buf, MAX_LEN);
	if (ret < 0) {
		printf("read %s failed: %s\n", argv[1], strerror(errno));
		close(fd);
		return -1;
	}

	close(fd);

	if (strstr(buf, "1"))
		printf("1\n");
	else if (strstr(buf, "0"))
		printf("0\n");
	else if (strstr(buf, "not sure"))
		printf("not sure\n");
	else
		printf("not sure\n");

	return 0;
}
