#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>

#define PAGE_SIZE 4096

int main(int argc, char **argv) {
	int fd;
	void *addr;
	size_t size;
	ssize_t ret;
	char buf[PAGE_SIZE];

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	size = lseek(fd, 0, SEEK_END);
	if (size < 0) {
		perror("lseek");
		exit(1);
	}

	addr = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	ret = read(fd, buf, PAGE_SIZE);
	if (ret < 0) {
		perror("read");
		exit(1);
	}

	if (ret!= PAGE_SIZE) {
		printf("read %ld bytes, expected %ld\n", ret, PAGE_SIZE);
		exit(1);
	}

	if (memcmp(buf, addr, PAGE_SIZE)!= 0) {
		printf("data mismatch\n");
		exit(1);
	}

	printf("data match\n");

	exit(0);
}
