	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	buf = addr;
	for (i = 0; i < PAGE_SIZE; i++)
		buf[i] = 0;

	munmap(addr, PAGE_SIZE);
	close(fd);

	return 0;
}
