	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return 1;
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		return 1;
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		return 1;
	}

	ret = read(fd, buf, BUF_SIZE);
	if (ret < 0) {
		perror("read");
		return 1;
	}

	if (strncmp(buf, "1", 1) == 0) {
		printf("1\n");
	} else if (strncmp(buf, "0", 1) == 0) {
		printf("0\n");
	} else {
		printf("not sure\n");
	}

	return 0;
}
