#define CWE_MAX_LEN 10
#define CWE_MAX_NUM 5

int main(int argc, char *argv[])
{
	char *cwe_list[CWE_MAX_NUM];
	char *cwe_str;
	char *cwe_str_tmp;
	int cwe_num = 0;
	int i;

	if (argc!= 2) {
		printf("Usage: %s <cwe_list>\n", argv[0]);
		return 0;
	}

	cwe_str = strdup(argv[1]);
	cwe_str_tmp = strtok(cwe_str, ",");
	while (cwe_str_tmp!= NULL) {
		if (cwe_num >= CWE_MAX_NUM) {
			printf("Too many CWEs\n");
			return 0;
		}

		cwe_list[cwe_num] = strdup(cwe_str_tmp);
		cwe_num++;
		cwe_str_tmp = strtok(NULL, ",");
	}

	printf("[\n");
	for (i = 0; i < cwe_num; i++) {
		if (i!= 0)
			printf(",\n");

		printf("\t\"CWE-%s\"", cwe_list[i]);
	}
	printf("\n]\n");

	return 0;
}
